projectRoot = pwd;
assert(isfile(fullfile(projectRoot,'README.md')), ...
    'Start MATLAB in the repository root.');
addpath(fullfile(projectRoot,'scripts'), ...
        fullfile(projectRoot,'models'), ...
        fullfile(projectRoot,'data'));
initialize_training_data(projectRoot);
open_system(fullfile(projectRoot,'models', ...
    'AircraftFeedbackControlLoop.slx'));
set_param('AircraftFeedbackControlLoop', ...
    'SimulationCommand','update');
run_training_simulations(projectRoot);
run_pitch_rate_limiter_tests(projectRoot);

dd = Simulink.data.dictionary.open( ...
 fullfile(projectRoot,'data','FCS_Data.sldd'));
sec = getSection(dd,'Design Data');
e = getEntry(sec,'FlightControlBus');
bus = getValue(e);
{bus.Elements.Name}
close(dd);
